//! #[::tokio::main]
//! async fn main() -> Result<(), iam::Error> {
//!     let config = aws_config::load_from_env().await;
//!     let client = aws_sdk_iam::Client::new(&config);
//!
//!     // ... make some calls with the client
//!
//!     Ok(())
//! }
